  if (RE_PHONE.test(v) || RE_EMAIL.test(v)) { setErr(account, accountMsg, ""); return true; }
  setErr(account, accountMsg, "账号格式不正确，请输入正确的手机号或邮箱");
  return false;
}

function checkPassword(showEmpty) {
  const v = password.value;
  if (!v) {
    if (showEmpty) { setErr(password, passwordMsg, "请输入登录密码"); return false; }
    setErr(password, passwordMsg, ""); return null;
  }
  if (/\s/.test(v)) { setErr(password, passwordMsg, "密码不能包含空格"); return false; }
  if (v.length < 8 || v.length > 20) {
    setErr(password, passwordMsg, "密码长度需为 8-20 位"); return false;
  }
  setErr(password, passwordMsg, ""); return true;
}

function setErr(input, msgEl, text) {
  msgEl.textContent = text;
  input.classList.toggle("err", !!text);
  refresh();
}

function refresh() {
  submitBtn.disabled = !(checkAccount(false) === true && checkPassword(false) === true);
}

account.addEventListener("input", () => checkAccount(false));
account.addEventListener("blur",  () => checkAccount(true));
password.addEventListener("input", () => checkPassword(false));
password.addEventListener("blur", () => checkPassword(true));

$("loginForm").addEventListener("submit", e => {
  const okA = checkAccount(true), okP = checkPassword(true);
  if (!(okA && okP)) { e.preventDefault(); return; }
  $("uaField").value = navigator.userAgent;
  submitBtn.disabled = true;
  submitBtn.textContent = "登录中…";
});

// 页签切换
$("tabQr").addEventListener("click", () => alert("请使用手机版 " + BRAND + " 扫码"));
